SCORING = ['accuracy', 'precision', 'recall', 'f1', 'roc_auc']
rows = []
for name, est in best.items():
    r = cross_validate(est, Xtr, ytr, cv=cv5, scoring=SCORING, n_jobs=1)
    rows.append({
        'Model': name,
        **{m.upper() if m == 'roc_auc' else m.capitalize():
           f"{r['test_'+m].mean():.4f} ± {r['test_'+m].std():.4f}"
           for m in SCORING}
    })
cv_df = pd.DataFrame(rows).set_index('Model')
display(cv_df)

cvF1 = {
    n: cross_validate(e, Xtr, ytr, cv=cv5, scoring='f1')['test_score']
    for n, e in best.items()
}
top = max(cvF1, key=lambda k: cvF1[k].mean())
print(f'Best CV model: {top}\n')
for n, s in cvF1.items():
    if n != top:
        p = stats.ttest_rel(cvF1[top], s).pvalue
        print(f'{top} vs {n}: mean diff={cvF1[top].mean()-s.mean():+.4f}  p={p:.4f}')
